on conflict(content_version_id,task_key,task_version) do nothing;

with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw17_20_geometric_v1' and status='draft'), defs(k,t,en,ru,uz) as (values
('p5_aw17_geometric_diagnostic','diagnostic','P5 AW17-20 Geometric diagnostic','Диагностика P5 AW17–20: geometric','P5 AW17–20 geometrik diagnostikasi'),('p5_geo02_learning','learning','Geometric probabilities learning','Геометрические вероятности: обучение','Geometrik ehtimollar: o‘rganish'),('p5_geo03_learning','learning','Geometric expectation learning','Ожидание geometric: обучение','Geometrik kutilma: o‘rganish'),('p5_geo02_retest','retest','GEO-02 delayed retest','GEO-02 отложенный ретест','GEO-02 kechiktirilgan retest'),('p5_geo03_retest','retest','GEO-03 delayed retest','GEO-03 отложенный ретест','GEO-03 kechiktirilgan retest'),('p5_aw17_geometric_mixed','mixed','P5 AW17-20 Geometric mixed transfer','P5 AW17–20: смешанный перенос geometric','P5 AW17–20 geometrik mixed transfer'))
insert into private.exam_prep_assessments(content_version_id,assessment_key,assessment_version,component_code,assessment_type,status,title_en,title_ru,title_uz)
select cv.id,d.k,'av1','P5',d.t,'approved',d.en,d.ru,d.uz from defs d cross join cv
